{"name": "write_file", "arguments": {"filename": "detect_shm_dropper.yar", "content": "rule Linux_ELF_Shm_Dropper {
    meta:
        description = "Detects ELF binaries referencing hidden files in /dev/shm"
        severity = "high"
    strings:
        $shm_path = "/dev/shm/.hidden" ascii
    condition:
        uint32(0) == 0x464c457f and $shm_path
}
"}}

